/**
 * @param {number[]} nums
 * @return {number}
 */
var maxAlternatingSum = function(nums) {
    const arr = nums
        .map(num => num * num)
        .sort((a, b) => a - b);

    let left = 0;
    let right = arr.length - 1;
    let res = 0;

    while (left <= right) {
        res += arr[right];
        right--;

        if (left <= right) {
            res -= arr[left];
            left++;
        }
    }

    return res;
};
